def cluster_states(grid):
    rows = len(grid)
    cols = len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    goal_state_value = 15
    policy_dict = {}

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != "X":
                policy_dict[(i, j)] = []

    def get_neighboring_states(state):
        neighbors = []

        for d in directions:
            x, y = state[0]+d[0], state[1]+d[1]

            if 0 <= x < rows and 0 <= y < cols and grid[x][y] != "X":
                neighbors.append((x, y))

        return neighbors

    def get_optimal_action_value(state):
        values = defaultdict(float)

        for next_state in get_neighboring_states(state):
            value = policy_dict[next_state][-1]
            transition_prob = 0.8
            values[state] += (transition_prob * value + (1 - transition_prob) * goal_state_value)

        return values

    def cluster():
        clusters = []

        for i in range(rows):
            for j in range(cols):
                if grid[i][j] != "X":
                    state = (i, j)

                    if policy_dict[state]:
                        optimal_action_value = get_optimal_action_value(state)

                        for other_state in policy_dict:
                            if optimal_action_value == policy_dict[other_state][-1]:
                                clusters.append([state, other_state])

    cluster()

    # Remove duplicates and return the list of clusters
    clusters = [list(set(cluster)) for cluster in set(tuple(sorted(cluster, key=lambda x: (x[0], x[1]))) for cluster in clusters)]

    return [[int(state[0]), int(state[1])] for state in clusters]

